# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar
func verify_data_column_sidecar*(sidecar: fulu.DataColumnSidecar):
                                 Result[void, cstring] =
  ## Verify if the data column sidecar is valid.

  if sidecar.index >= NUMBER_OF_COLUMNS:
    return err("Data column sidecar index exceeds the NUMBER_OF_COLUMNS")

  if sidecar.kzg_commitments.len == 0:
    return err("Data column contains zero blob")

  if sidecar.column.len != sidecar.kzg_commitments.len or
      sidecar.column.len != sidecar.kzg_proofs.len:
    return err("Data column length must be equal to the number of commitments/proofs")

  ok()

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar_inclusion_proof
func verify_data_column_sidecar_inclusion_proof*(sidecar: fulu.DataColumnSidecar):
                                                 Result[void, cstring] =
  ## Verify if the given KZG commitments included in the given beacon block.
  let gindex =
    KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH_GINDEX.GeneralizedIndex
  if not is_valid_merkle_branch(
      hash_tree_root(sidecar.kzg_commitments),
      sidecar.kzg_commitments_inclusion_proof,
      KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH.int,
      get_subtree_index(gindex),
      sidecar.signed_block_header.message.body_root):

    return err("DataColumnSidecar: Inclusion proof is invalid")

  ok()

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
proc verify_data_column_sidecar_kzg_proofs*(sidecar: fulu.DataColumnSidecar):
                                            Result[void, cstring] =
  ## Verify if the KZG proofs are correct.

  # Iterate through the cell indices
  var cellIndices = newSeqOfCap[CellIndex](sidecar.column.len)
  for _ in 0..<sidecar.column.len:
    cellIndices.add(CellIndex(sidecar.index))

  let res = verifyCellKzgProofBatch(
      sidecar.kzg_commitments.asSeq, cellIndices, sidecar.column.asSeq,
      sidecar.kzg_proofs.asSeq).valueOr:
    return err("DataColumnSidecar: validation error")

  if not res:
    return err("DataColumnSidecar: validation failed")

  ok()

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.0/specs/phase0/beacon-chain.md#get_beacon_proposer_index
func get_beacon_proposer_index*(
    state: ForkyBeaconState, cache: var StateCache, slot: Slot):
    Opt[ValidatorIndex] =
  let epoch = get_current_epoch(state)
  if slot.epoch() != epoch:
    # compute_proposer_index depends on `effective_balance`, therefore the
    # beacon proposer index can only be computed for the "current" epoch:
    # https://github.com/ethereum/consensus-specs/pull/772#issuecomment-475574357
    return Opt.none(ValidatorIndex)
  when typeof(state).kind >= ConsensusFork.Fulu:
    let pi = Opt.some(ValidatorIndex item(state.proposer_lookahead, slot mod SLOTS_PER_EPOCH))
    cache.beacon_proposer_indices[slot] = pi
    return pi
  else:
    cache.beacon_proposer_indices.withValue(slot, proposer) do:
      return proposer[]
    do:
      ## Return the beacon proposer index at the current slot.
      var buffer: array[32 + 8, byte]
      buffer[0..31] = get_seed(state, epoch, DOMAIN_BEACON_PROPOSER).data
      # There's exactly one beacon proposer per slot - the same validator may
      # however propose several times in the same epoch (however unlikely)
      let indices = get_active_validator_indices(state, epoch)
      var res: Opt[ValidatorIndex]
      for epoch_slot in epoch.slots():
        buffer[32..39] = uint_to_bytes(epoch_slot.asUInt64)
        let seed = eth2digest(buffer)
        let pi = compute_proposer_index(state, indices, seed)
        if epoch_slot == slot:
          res = pi
        cache.beacon_proposer_indices[epoch_slot] = pi
      return res

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.2/specs/fulu/beacon-chain.md#new-get_beacon_proposer_indices
func get_beacon_proposer_indices*(
    state: ForkyBeaconState, epoch: Epoch
): seq[Opt[ValidatorIndex]] =
  ## Return the proposer indices for the given `epoch`.
  let indices = get_active_validator_indices(state, epoch)
  let seed = get_seed(state, epoch, DOMAIN_BEACON_PROPOSER)

  debugGloasComment "temporary workaround for Gloas"
  when typeof(state).kind >= ConsensusFork.Gloas:
    let proposers = compute_proposer_indices(state, epoch, seed, indices)
    proposers.mapIt(Opt.some(it))
  else:
    compute_proposer_indices(state, epoch, seed, indices)

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.0/specs/phase0/beacon-chain.md#get_beacon_proposer_index
func get_beacon_proposer_indices*(
    state: ForkyBeaconState, shuffled_indices: openArray[ValidatorIndex], epoch: Epoch):
    seq[Opt[ValidatorIndex]] =
  ## Return the beacon proposer indices at the current epoch, using shuffled
  ## rather than sorted active validator indices.
  when typeof(state).kind < ConsensusFork.Fulu:
    var
      buffer {.noinit.}: array[32 + 8, byte]
      res: seq[Opt[ValidatorIndex]]

    buffer[0..31] = get_seed(state, epoch, DOMAIN_BEACON_PROPOSER).data
    let epoch_shuffle_seed = get_seed(state, epoch, DOMAIN_BEACON_ATTESTER)

    for epoch_slot in epoch.slots():
      buffer[32..39] = uint_to_bytes(epoch_slot.asUInt64)
      res.add (
        compute_proposer_index(state, shuffled_indices, eth2digest(buffer)) do:
          compute_inverted_shuffled_index(
            shuffled_index, seq_len, epoch_shuffle_seed))

    res
  else:
    # Not using shuffled indices here is not a bug,
    # as the method of computing proposer in the below
    # function does not require shuffled indices post Fulu
    get_beacon_proposer_indices(state, epoch)

